css:
:root{--ink: #1b201e; --text: #2f3634; --muted: #4a5450; --teal: #0d4a40; --teal-deep: #0a3b33; --band: #f2f5f3; --line: #d2d9d5; --on-dark: #eef3f0; --radius: 2px;}
*{box-sizing: border-box;}
body{margin: 0px; background: rgb(255, 255, 255); color: var(--text); font-family: "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", "Source Han Sans SC", "Noto Sans CJK SC", sans-serif; font-size: 16px; line-height: 1.65;}
h1, h2, h3{color: var(--ink); font-weight: 700; line-height: 1.3; letter-spacing: 0.01em;}
p{margin: 0px 0px 14px; max-width: 38em;}
ul, ol{margin: 0px;}
a{color: var(--teal);}
a:focus-visible{outline: 2px solid var(--teal); outline-offset: 3px;}
img{max-width: 100%;}
.nw{white-space: nowrap;}
.container{max-width: 1120px; margin: 0px auto; padding: 0px 24px;}
.site-header{background: rgb(255, 255, 255); border-bottom: 2px solid var(--teal);}
.header-inner{max-width: 1120px; margin: 0px auto; padding: 0px 24px; height: 66px; display: flex; align-items: center; justify-content: space-between; gap: 24px;}
.brand{display: flex; align-items: center; gap: 10px; text-decoration: none; color: var(--ink);}
.brand-mark{position: relative; display: block; width: 24px; height: 24px; border: 2px solid var(--teal); flex: 0 0 auto;}
.brand-mark-inner{position: absolute; inset: 4px; border: 1px solid var(--teal);}
.brand-name{font-size: 1.06rem; font-weight: 700; letter-spacing: 0.06em; white-space: nowrap;}
.site-nav ul{display: flex; flex-wrap: wrap; gap: 22px; margin: 0px; padding: 0px; list-style: none;}
.site-nav a{display: inline-block; color: var(--text); text-decoration: none; font-size: 0.95rem; padding: 3px 0px; border-bottom: 2px solid transparent;}
.site-nav a:hover, .site-nav a:focus{color: var(--teal); border-bottom-color: var(--teal);}
.hero{background: var(--teal); color: var(--on-dark); padding: 64px 0px 58px;}
.hero h1{color: rgb(255, 255, 255); font-size: 2.4rem; margin: 0px; max-width: 22em;}
.hero--compact{padding: 50px 0px 44px;}
.hero--compact h1{font-size: 2rem;}
.hero-lede{margin: 16px 0px 0px; color: rgb(219, 230, 225); font-size: 1.1rem; line-height: 1.7; max-width: 32em;}
.hero-actions{margin: 28px 0px 0px;}
.btn{display: inline-block; background: rgb(255, 255, 255); color: var(--teal-deep); border: 2px solid rgb(255, 255, 255); border-radius: var(--radius); padding: 11px 22px; font-weight: 700; text-decoration: none;}
.btn:hover, .btn:focus{background: transparent; color: rgb(255, 255, 255);}
.page-head{padding: 52px 0px 40px; border-bottom: 1px solid var(--line);}
.page-head h1{font-size: 2rem; margin: 0px 0px 12px; max-width: 22em;}
.page-head + .section{border-top-width: medium; border-top-style: none; border-top-color: currentcolor;}
.section{padding: 56px 0px; border-top: 1px solid var(--line);}
.section--band{background: var(--band);}
.section-title{font-size: 1.55rem; margin: 0px 0px 12px;}
.section-lead{color: var(--muted); margin: 0px 0px 16px;}
h3{font-size: 1.08rem; margin: 24px 0px 8px;}
.sub-block{margin-top: 44px; padding-top: 30px; border-top: 1px solid var(--line);}
.section-more{margin: 22px 0px 0px;}
.text-link{color: var(--teal); font-weight: 700; text-decoration: underline; text-underline-offset: 3px;}
.split-2-1{display: grid; grid-template-columns: 2fr 1fr; gap: 40px; align-items: start;}
.split-1-1{display: grid; grid-template-columns: 1fr 1fr; gap: 40px; align-items: start;}
.split-text-thumb{display: grid; grid-template-columns: 1fr 300px; gap: 40px; align-items: start;}
.split-content-thumb{display: grid; grid-template-columns: 1fr 320px; gap: 40px; align-items: start;}
.dir-list{list-style: none; margin: 6px 0px 0px; padding: 0px; border-top: 1px solid var(--line);}
.dir-list li{display: flex; flex-wrap: wrap; align-items: baseline; gap: 2px 20px; padding: 14px 0px; border-bottom: 1px solid var(--line);}
.dir-name{font-size: 1.06rem; font-weight: 700; color: var(--ink); text-decoration: none; white-space: nowrap;}
.dir-name:hover, .dir-name:focus{color: var(--teal); text-decoration: underline;}
.dir-note{flex: 1 1 260px; min-width: 0px; color: var(--muted); font-size: 0.97rem;}
.thumb{margin: 0px;}
.thumb img{display: block; width: 100%; height: auto; border: 1px solid var(--line); border-radius: var(--radius); background: var(--band);}
.thumb figcaption{margin-top: 8px; font-size: 0.8rem; line-height: 1.5; color: var(--muted);}
.thumb--small{max-width: 320px;}
.side-note{background: var(--band); border-left: 3px solid var(--teal); padding: 20px 22px;}
.side-note h3{margin: 0px 0px 8px; font-size: 1rem; color: var(--teal);}
.side-note p{margin: 0px 0px 10px; font-size: 0.95rem;}
.side-note .thumb{margin-top: 16px;}
.timeline{margin: 0px; padding: 0px;}
.timeline .tl-item{display: grid; grid-template-columns: 110px 1fr; gap: 16px; padding: 10px 0px; border-bottom: 1px solid var(--line);}
.timeline dt{font-weight: 700; color: var(--teal); white-space: nowrap; font-variant-numeric: tabular-nums;}
.timeline dd{margin: 0px;}
.figures{display: flex; flex-wrap: wrap; gap: 24px 64px; margin: 0px 0px 26px; padding: 0px; list-style: none;}
.fig-label{display: block; font-size: 0.86rem; color: var(--muted);}
.fig-value{display: block; font-size: 1.9rem; font-weight: 700; color: var(--teal); line-height: 1.25; font-variant-numeric: tabular-nums;}
.eq-list{list-style: none; margin: 0px; padding: 0px; font-variant-numeric: tabular-nums;}
.eq-list li{display: flex; flex-wrap: wrap; justify-content: space-between; gap: 4px 16px; padding: 9px 0px; border-bottom: 1px solid var(--line); font-size: 0.98rem;}
.eq-name{color: var(--ink);}
.eq-qty{color: var(--teal); font-weight: 700;}
.steps{list-style: decimal; margin: 0px; padding-left: 1.5em; max-width: 34em;}
.steps li{padding: 5px 0px 5px 4px; line-height: 1.7;}
.steps li::marker{color: var(--teal); font-weight: 700;}
.record{display: grid; grid-template-columns: 170px 1fr; gap: 6px 28px; padding: 18px 0px; border-top: 1px solid var(--line);}
.record h3{margin: 0px; font-size: 1.02rem; color: var(--teal);}
.record p{margin: 0px;}
.cert-list{list-style: none; margin: 0px 0px 12px; padding: 0px;}
.cert-list li{display: flex; flex-wrap: wrap; justify-content: space-between; gap: 4px 16px; padding: 9px 0px; border-bottom: 1px solid var(--line); font-variant-numeric: tabular-nums;}
.cert-name{color: var(--ink);}
.cert-state{color: var(--teal); font-weight: 700;}
.note{font-size: 0.9rem; color: var(--muted);}
.qa{margin: 0px; max-width: 38em;}
.qa dt{font-weight: 700; color: var(--ink); font-size: 1.02rem; padding-top: 18px; border-top: 1px solid var(--line);}
.qa dd{margin: 6px 0px 0px; padding-bottom: 18px;}
.data-list{list-style: none; margin: 0px 0px 16px; padding: 0px; max-width: 38em;}
.data-list li{position: relative; padding: 9px 0px 9px 18px; border-bottom: 1px solid var(--line);}
.data-list li::before{content: ""; position: absolute; left: 0px; top: 1.15em; width: 7px; height: 2px; background: var(--teal);}
.update-list{list-style: none; margin: 0px; padding: 0px;}
.update-list li{display: grid; grid-template-columns: 110px 1fr; gap: 4px 20px; padding: 10px 0px; border-bottom: 1px solid var(--line);}
.update-date{color: var(--teal); font-weight: 700; white-space: nowrap; font-variant-numeric: tabular-nums;}
.contact-list{display: grid; grid-template-columns: 80px 1fr; gap: 10px 16px; margin: 0px; font-variant-numeric: tabular-nums;}
.contact-list dt{color: var(--muted); font-size: 0.95rem;}
.contact-list dd{margin: 0px;}
.spec-table{width: 100%; border-collapse: collapse; font-size: 0.96rem; font-variant-numeric: tabular-nums;}
.spec-table caption{text-align: left; font-size: 0.86rem; color: var(--muted); padding: 0px 0px 8px;}
.spec-table th{width: 40%; text-align: left; vertical-align: top; font-weight: 500; color: var(--muted); padding: 11px 16px 11px 0px; border-bottom: 1px solid var(--line);}
.spec-table td{vertical-align: top; padding: 11px 0px; border-bottom: 1px solid var(--line); color: var(--ink);}
.spec-grid{display: grid; grid-template-columns: 1fr 1fr; gap: 0px 36px; margin: 18px 0px 0px;}
.spec-item{border-bottom: 1px solid var(--line); padding: 10px 0px;}
.spec-grid dt, .spec-list dt{font-size: 0.86rem; color: var(--muted); margin: 0px;}
.spec-grid dd{margin: 2px 0px 0px; color: var(--ink); font-variant-numeric: tabular-nums;}
.spec-list{display: grid; grid-template-columns: 150px 1fr; margin: 18px 0px 0px; font-variant-numeric: tabular-nums;}
.spec-list dt{padding: 10px 12px 10px 0px; border-bottom: 1px solid var(--line);}
.spec-list dd{margin: 0px; padding: 10px 0px; border-bottom: 1px solid var(--line); color: var(--ink); font-size: 0.96rem;}
.ind-list{display: flex; flex-wrap: wrap; gap: 10px 32px; list-style: none; margin: 18px 0px 0px; padding: 0px; font-size: 1.02rem; color: var(--ink);}
.ind-list li{border-left: 3px solid var(--teal); padding-left: 12px;}
.site-footer{background: var(--teal-deep); color: var(--on-dark); padding: 44px 0px 36px;}
.footer-grid{display: grid; grid-template-columns: 1.5fr 1fr 1.2fr; gap: 32px 40px;}
.footer-name{font-size: 1.1rem; font-weight: 700; color: rgb(255, 255, 255); margin: 0px 0px 10px; letter-spacing: 0.04em;}
.footer-title{font-size: 0.85rem; letter-spacing: 0.1em; color: rgb(169, 195, 187); margin: 0px 0px 10px;}
.footer-col p{color: rgb(223, 233, 228); max-width: 34em;}
.footer-col p:last-child{margin-bottom: 0px;}
.footer-nav{list-style: none; margin: 0px; padding: 0px;}
.footer-nav li{padding: 4px 0px;}
.footer-nav a{color: rgb(238, 243, 240); text-decoration: none;}
.footer-nav a:hover, .footer-nav a:focus{color: rgb(255, 255, 255); text-decoration: underline;}
.site-footer a:focus-visible{outline: rgb(255, 255, 255) solid 2px; outline-offset: 3px;}
@media (max-width: 900px){.split-2-1, .split-1-1, .split-text-thumb, .split-content-thumb{grid-template-columns: 1fr; gap: 28px;}
.footer-grid{grid-template-columns: 1fr 1fr;}}
@media (max-width: 700px){.spec-table, .spec-table tbody, .spec-table tr, .spec-table th, .spec-table td{display: block; width: auto;}
.spec-table th{padding: 10px 0px 0px; border-bottom-width: medium; border-bottom-style: none; border-bottom-color: currentcolor; font-size: 0.86rem;}
.spec-table td{padding: 2px 0px 12px; border-bottom: 1px solid var(--line);}
.spec-grid{grid-template-columns: 1fr;}}
@media (max-width: 640px){.container{padding: 0px 16px;}
.header-inner{height: auto; flex-direction: column; align-items: flex-start; gap: 2px; padding: 10px 16px;}
.site-nav ul{gap: 18px;}
.hero{padding: 38px 0px 34px;}
.hero h1{font-size: 1.7rem;}
.hero--compact{padding: 32px 0px 28px;}
.hero--compact h1, .page-head h1{font-size: 1.5rem;}
.hero-lede{font-size: 1rem; margin-top: 12px;}
.page-head{padding: 30px 0px 26px;}
.section{padding: 30px 0px;}
.section-title{font-size: 1.3rem;}
.sub-block{margin-top: 26px; padding-top: 22px;}
.figures{gap: 18px 40px; margin-bottom: 20px;}
.fig-value{font-size: 1.5rem;}
.timeline .tl-item{grid-template-columns: 1fr; gap: 2px; padding: 9px 0px;}
.record{grid-template-columns: 1fr; gap: 4px;}
.update-list li{grid-template-columns: 1fr; gap: 2px;}
.contact-list{grid-template-columns: 1fr; gap: 2px;}
.contact-list dd{margin-bottom: 10px;}
.spec-list{grid-template-columns: 1fr;}
.spec-list dt{padding: 10px 0px 0px; border-bottom-width: medium; border-bottom-style: none; border-bottom-color: currentcolor;}
.spec-list dd{padding: 2px 0px 12px;}
.footer-grid{grid-template-columns: 1fr; gap: 24px;}}
